/**
 * Verified Quran data for Ilm Journey: Al-Fatiha + the complete Juz ʿAmma (78–114) and a collection of Quranic
 * duas. All Arabic text, transliteration and translations are generated by `scripts/generate-quran.mjs` from
 * api.alquran.cloud (Tanzil Uthmani text) — never typed by hand. See ./README.md for provenance.
 *
 * Plain TypeScript without app dependencies, so any feature (Learn, Quran, …) can use it.
 */
import duasData from './data/duas.json';
import surahsData from './data/surahs.json';

export type QuranLanguage = 'en' | 'de' | 'bs';
export type QuranText = Record<QuranLanguage, string>;

export const QURAN_LANGUAGES: readonly QuranLanguage[] = ['en', 'de', 'bs'];

export interface Ayah {
  numberInSurah: number;
  /** Position in the whole Quran (1–6236); used for the optional streamed recitation. */
  globalNumber: number;
  arabic: string;
  transliteration: string;
  translation: QuranText;
}

export type SurahDifficulty = 'easy' | 'medium' | 'hard';

export interface Surah {
  number: number;
  nameArabic: string;
  nameTransliterated: string;
  /** English meaning of the surah name (same field as islam-quest). */
  nameMeaning: string;
  /** Localised meaning; `de` currently falls back to English (no verified German source). */
  nameMeaningLocalized?: QuranText;
  revelationType: 'makki' | 'madani';
  ayahCount: number;
  /** Juz in which the surah starts. */
  juz: number;
  /** Memorisation hint from the ayah count: easy ≤ 8, medium ≤ 20, hard > 20. */
  difficulty: SurahDifficulty;
  /** Suggested memorisation order (1 = first): Al-Fatiha, then easy → hard, from An-Nas backwards. */
  memorizationOrder: number;
  ayahs: Ayah[];
}

export type DuaTheme =
  | 'acceptance'
  | 'community'
  | 'ease'
  | 'family'
  | 'forgiveness'
  | 'goodness'
  | 'gratitude'
  | 'guidance'
  | 'knowledge'
  | 'parents'
  | 'protection'
  | 'provision'
  | 'reflection'
  | 'relief'
  | 'steadfastness';

export interface DuaAyah extends Ayah {
  surah: number;
}

/** A supplication that is a verbatim Quran passage; always presented as the full ayah(s). */
export interface QuranicDua {
  id: string;
  /** "21:87" or "20:25-28". */
  ref: string;
  theme: DuaTheme;
  /** Editorial title (not Quran). */
  title: QuranText;
  /** One neutral sentence on who says it in the Quran, ending with the reference (editorial, not Quran). */
  context: QuranText;
  surah: { number: number; nameArabic: string; nameTransliterated: string; nameMeaning: string; ayahCount: number };
  ayahs: DuaAyah[];
  sourceName: string;
  sourceReference: string;
}

export interface QuranSource {
  text: string;
  translations: QuranText;
  transliteration: string;
  api: string;
  surahNamesBs: string;
  generated: string;
  generator: string;
}

export const QURAN_SOURCE: QuranSource = surahsData.source;
/** The Basmala as given in the source (Al-Fatiha 1:1). Not part of ayah 1 of other surahs. */
export const BASMALA: string = surahsData.basmala;

const SURAHS: readonly Surah[] = surahsData.surahs as Surah[];
const DUAS: readonly QuranicDua[] = duasData.duas as QuranicDua[];

/** Surahs in mushaf order (default) or in the suggested memorisation order. */
export function listSurahs(order: 'mushaf' | 'memorization' = 'mushaf'): readonly Surah[] {
  if (order === 'mushaf') return SURAHS;
  return [...SURAHS].sort((a, b) => a.memorizationOrder - b.memorizationOrder);
}

export function getSurah(number: number): Surah | undefined {
  return SURAHS.find((s) => s.number === number);
}

export function getAyah(surahNumber: number, ayahNumber: number): Ayah | undefined {
  return getSurah(surahNumber)?.ayahs.find((a) => a.numberInSurah === ayahNumber);
}

export function listDuas(): readonly QuranicDua[] {
  return DUAS;
}

export function getDua(id: string): QuranicDua | undefined {
  return DUAS.find((d) => d.id === id);
}

/** Duas grouped by theme, themes in order of first appearance. */
export function duasByTheme(): Partial<Record<DuaTheme, QuranicDua[]>> {
  const groups: Partial<Record<DuaTheme, QuranicDua[]>> = {};
  for (const dua of DUAS) (groups[dua.theme] ??= []).push(dua);
  return groups;
}

const ARABIC_LETTER = /[\u0621-\u064A\u0671-\u06D3]/;

/** Splits an ayah into words; tokens without an Arabic letter (e.g. stop marks) are dropped. */
export function ayahWords(text: string): string[] {
  return text.split(/\s+/).filter((token) => ARABIC_LETTER.test(token));
}

/**
 * Optional recitation audio (Mishary Alafasy, 128 kbps, via the Islamic Network CDN) — the same stream as
 * islam-quest's "Listen". Only fetched when the user taps play; the app works fully offline without it.
 */
export const RECITATION_SOURCE = 'Mishary Rashid Alafasy — cdn.islamic.network';

export function audioUrlForAyah(globalNumber: number): string {
  if (!Number.isInteger(globalNumber) || globalNumber < 1 || globalNumber > 6236) {
    throw new RangeError(`Invalid global ayah number: ${globalNumber}`);
  }
  return `https://cdn.islamic.network/quran/audio/128/ar.alafasy/${globalNumber}.mp3`;
}
